package dao.device;

import config.DatabaseConnection;
import java.sql.*;
import java.util.ArrayList;
import java.util.List;
import model.device.MaintenanceModels.*;

public final class MaintenanceDAO {
    public List<Schedule> schedules(String q){String sql="SELECT b.MaBaoDuong,b.MaThietBi,t.TenThietBi,b.NgayDuKien,b.NgayThucHien,b.NoiDung,b.DonViThucHien,b.MaNhanVienPhuTrach,b.ChiPhi,b.TrangThai FROM dbo.LichBaoDuong b JOIN dbo.ThietBi t ON t.MaThietBi=b.MaThietBi WHERE (?='' OR b.MaThietBi LIKE ? OR t.TenThietBi LIKE ? OR b.NoiDung LIKE ?) ORDER BY b.NgayDuKien DESC";List<Schedule>x=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){bind(s,q);try(ResultSet r=s.executeQuery()){while(r.next())x.add(new Schedule(r.getLong(1),r.getString(2),r.getString(3),date(r.getDate(4)),date(r.getDate(5)),r.getString(6),r.getString(7),r.getString(8),r.getBigDecimal(9),r.getString(10)));}return List.copyOf(x);}catch(SQLException e){throw err("tải lịch bảo dưỡng",e);}}
    public List<Repair> repairs(String q){String sql="SELECT s.MaSuaChua,s.MaThietBi,t.TenThietBi,CAST(s.NgayBaoHong AS date),s.MoTaSuCo,s.NgaySua,s.DonViSuaChua,s.ChiPhi,s.TrangThai,s.MaNhanVienTiepNhan,s.GhiChu FROM dbo.SuaChuaThietBi s JOIN dbo.ThietBi t ON t.MaThietBi=s.MaThietBi WHERE (?='' OR s.MaThietBi LIKE ? OR t.TenThietBi LIKE ? OR s.MoTaSuCo LIKE ?) ORDER BY s.NgayBaoHong DESC";List<Repair>x=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){bind(s,q);try(ResultSet r=s.executeQuery()){while(r.next())x.add(new Repair(r.getLong(1),r.getString(2),r.getString(3),date(r.getDate(4)),r.getString(5),date(r.getDate(6)),r.getString(7),r.getBigDecimal(8),r.getString(9),r.getString(10),r.getString(11)));}return List.copyOf(x);}catch(SQLException e){throw err("tải phiếu sửa chữa",e);}}
    public void save(Schedule d){String sql=d.id()==null?"INSERT INTO dbo.LichBaoDuong(MaThietBi,NgayDuKien,NgayThucHien,NoiDung,DonViThucHien,MaNhanVienPhuTrach,ChiPhi,TrangThai) VALUES(?,?,?,?,?,?,?,?)":"UPDATE dbo.LichBaoDuong SET MaThietBi=?,NgayDuKien=?,NgayThucHien=?,NoiDung=?,DonViThucHien=?,MaNhanVienPhuTrach=?,ChiPhi=?,TrangThai=? WHERE MaBaoDuong=?";try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){int i=1;s.setString(i++,d.deviceId());setDate(s,i++,d.expectedDate());setDate(s,i++,d.completedDate());s.setNString(i++,d.content());s.setNString(i++,d.vendor());s.setString(i++,empty(d.employeeId()));if(d.cost()==null)s.setNull(i++,Types.DECIMAL);else s.setBigDecimal(i++,d.cost());s.setString(i++,d.status());if(d.id()!=null)s.setLong(i,d.id());s.executeUpdate();}catch(SQLException e){throw err("lưu lịch bảo dưỡng",e);}}
    public void save(Repair d){String sql=d.id()==null?"INSERT INTO dbo.SuaChuaThietBi(MaThietBi,MoTaSuCo,NgaySua,DonViSuaChua,ChiPhi,TrangThai,MaNhanVienTiepNhan,GhiChu) VALUES(?,?,?,?,?,?,?,?)":"UPDATE dbo.SuaChuaThietBi SET MaThietBi=?,MoTaSuCo=?,NgaySua=?,DonViSuaChua=?,ChiPhi=?,TrangThai=?,MaNhanVienTiepNhan=?,GhiChu=? WHERE MaSuaChua=?";try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){int i=1;s.setString(i++,d.deviceId());s.setNString(i++,d.description());setDate(s,i++,d.repairedDate());s.setNString(i++,d.vendor());if(d.cost()==null)s.setNull(i++,Types.DECIMAL);else s.setBigDecimal(i++,d.cost());s.setString(i++,d.status());s.setString(i++,empty(d.employeeId()));s.setNString(i++,d.note());if(d.id()!=null)s.setLong(i,d.id());s.executeUpdate();}catch(SQLException e){throw err("lưu phiếu sửa chữa",e);}}
    public void deleteSchedule(long id){delete("DELETE FROM dbo.LichBaoDuong WHERE MaBaoDuong=?",id,"xóa lịch bảo dưỡng");}public void deleteRepair(long id){delete("DELETE FROM dbo.SuaChuaThietBi WHERE MaSuaChua=?",id,"xóa phiếu sửa chữa");}
    private static void bind(PreparedStatement s,String q)throws SQLException{String k=q==null?"":q.trim();s.setString(1,k);s.setString(2,"%"+k+"%");s.setString(3,"%"+k+"%");s.setString(4,"%"+k+"%");}private static void setDate(PreparedStatement s,int i,java.time.LocalDate d)throws SQLException{if(d==null)s.setNull(i,Types.DATE);else s.setDate(i,Date.valueOf(d));}private static java.time.LocalDate date(Date d){return d==null?null:d.toLocalDate();}private static String empty(String s){return s==null||s.isBlank()?null:s.trim();}private static void delete(String sql,long id,String op){try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setLong(1,id);s.executeUpdate();}catch(SQLException e){throw err(op,e);}}private static DeviceDAOException err(String op,Exception e){return new DeviceDAOException("Không thể "+op+". Chi tiết hệ thống: "+e.getMessage(),e);}
}
